const status=document.getElementById('embedStatus');const output=document.getElementById('embedOutput');const modal=document.getElementById('embedModal');const modalImage=document.getElementById('embedModalImage');let mode='studio';
document.querySelectorAll('.embed-option').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.embed-option').forEach(x=>x.classList.remove('active'));btn.classList.add('active');mode=btn.dataset.mode}));
document.getElementById('embedGenerate').addEventListener('click',()=>{const model=document.getElementById('embedModel').value.trim();if(!model){status.innerHTML='<i></i> Укажите модель техники';return}status.innerHTML='<i></i> Запрос подготовлен: '+model+' · '+mode+'. Подключите API генератора, чтобы получить реальные кадры.';window.parent.postMessage({type:'techshot:request',model,mode},'*')});
document.getElementById('embedPhotos').addEventListener('change',event=>{const files=[...event.target.files];if(!files.length)return;output.innerHTML='';files.forEach(file=>{const url=URL.createObjectURL(file);const card=document.createElement('article');card.className='embed-result';const image=document.createElement('img');image.src=url;image.alt=file.name;image.addEventListener('click',()=>{modalImage.src=url;modal.classList.add('open');modal.setAttribute('aria-hidden','false')});const meta=document.createElement('div');const name=document.createElement('small');name.textContent=file.name;const download=document.createElement('button');download.type='button';download.textContent='⇩ Скачать';download.addEventListener('click',()=>{const a=document.createElement('a');a.href=url;a.download=file.name;a.click()});meta.append(name,download);card.append(image,meta);output.append(card)});status.innerHTML='<i></i> Загружено '+files.length+' фото. Нажмите на кадр, чтобы рассмотреть его в полном размере.'});
modal.addEventListener('click',event=>{if(event.target===modal||event.target.tagName==='BUTTON'){modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}});
